    $(function () {
        var hub = $.connection.qrHub;
        let isFirstLoad = true;

        hub.client.updateQrDashboard = function (data) {


            const formatPercent = (percent) => {
                let phanTram = parseFloat(percent);
                if (isNaN(phanTram) || phanTram <= 0) return "0.0";
                let phanTramGioiHan = Math.min(phanTram, 100);

                if (phanTramGioiHan < 0.1) {
                    return phanTramGioiHan.toFixed(3);
                }
                return phanTramGioiHan.toFixed(1);
            };

            const calculatePercent = (thucHien, keHoach) => {
                if (!keHoach || keHoach <= 0) return 0;
                return (thucHien / keHoach) * 100;
            };


            const updateUI = (selector, newValue, duration, suffix) => {
                let el = $(selector);
                let oldValue = el.data('raw-value');

                el.data('raw-value', newValue);

                if (isFirstLoad) {

                    animateNumber(selector, newValue, duration, suffix);
                } else {

                    if (oldValue !== undefined && Number(oldValue) !== Number(newValue)) {

                        let formattedText = new Intl.NumberFormat('vi-VN').format(newValue || 0) + suffix;
                        el.text(formattedText);


                        el.removeClass('highlight-flash');
                        void el[0].offsetWidth;
                        el.addClass('highlight-flash');
                    }
                }
            };

            const updateProgressUI = (barSelector, textSelector, newPercentRaw) => {
                let elText = $(textSelector);
                let oldPercent = elText.data('raw-value');
                elText.data('raw-value', newPercentRaw);

                let formattedPercent = newPercentRaw;
                let textHienThi = 'Tỷ lệ thanh toán lũy kế ' + formattedPercent + '%';

                if (isFirstLoad) {
                    $(barSelector).css('width', formattedPercent + '%');
                    elText.text(textHienThi);
                } else {
                    if (oldPercent !== undefined && Number(oldPercent) !== Number(newPercentRaw)) {
                        $(barSelector).css('width', formattedPercent + '%');
                        elText.text(textHienThi);


                        elText.removeClass('highlight-flash');
                        void elText[0].offsetWidth;
                        elText.addClass('highlight-flash');
                    }
                }
            };

            updateUI('#qrTongDon', data.Tong.TongDon, 500, '');
            updateUI('#qrTongSHD', data.Tong.TongSoHoaDon, 1000, '');
            updateUI('#qrTongTien', data.Tong.TongTien, 1000, ' VNĐ');
            updateUI('#qrDonTT', data.Tong.TongDonThanhToan, 1000, '');
            updateUI('#qrSHDTT', data.Tong.TongSoHoaDonThanhToan, 1000, '');
            updateUI('#qrTienTT', data.Tong.TongTienThanhToan, 1000, ' VNĐ');

            let tyLeTong = calculatePercent(data.Tong.TongTienThanhToan, data.Tong.TongTien);
            updateProgressUI('#qrTyTrongProgress', '#qrTyTrongTyLe', data.Tong.TyLeLuyKe);


            updateUI('#qrTongDonQLKH1', data.Qlkh1.TongDon, 500, '');
            updateUI('#qrTongSHDQLKH1', data.Qlkh1.TongSoHoaDon, 1000, '');
            updateUI('#qrTongTienQLKH1', data.Qlkh1.TongTien, 1000, ' VNĐ');
            updateUI('#qrDonTTQLKH1', data.Qlkh1.TongDonThanhToan, 1000, '');
            updateUI('#qrSHDTTQLKH1', data.Qlkh1.TongSoHoaDonThanhToan, 1000, '');
            updateUI('#qrTienTTQLKH1', data.Qlkh1.TongTienThanhToan, 1000, ' VNĐ');

            let tyLeQlkh1 = calculatePercent(data.Qlkh1.TongTienThanhToan, data.Qlkh1.TongTien);
            updateProgressUI('#qrTyTrongProgressQLKH1', '#qrTyTrongTyLeQLKH1', data.Qlkh1.TyLeLuyKe);


            updateUI('#qrTongDonQLKH2', data.Qlkh2.TongDon, 500, '');
            updateUI('#qrTongSHDQLKH2', data.Qlkh2.TongSoHoaDon, 1000, '');
            updateUI('#qrTongTienQLKH2', data.Qlkh2.TongTien, 1000, ' VNĐ');
            updateUI('#qrDonTTQLKH2', data.Qlkh2.TongDonThanhToan, 1000, '');
            updateUI('#qrSHDTTQLKH2', data.Qlkh2.TongSoHoaDonThanhToan, 1000, '');
            updateUI('#qrTienTTQLKH2', data.Qlkh2.TongTienThanhToan, 1000, ' VNĐ');

            let tyLeQlkh2 = calculatePercent(data.Qlkh2.TongTienThanhToan, data.Qlkh2.TongTien);
            updateProgressUI('#qrTyTrongProgressQLKH2', '#qrTyTrongTyLeQLKH2', data.Qlkh2.TyLeLuyKe);

            isFirstLoad = false;
        };

        $.connection.hub.start().done(function () {
            console.log("Đã kết nối Realtime Dashboard QR!");
        }).fail(function (err) {
            console.error("Lỗi kết nối SignalR: " + err);
        });
    });
