            });
        function updateHighlightValue(selector, newValue) {

            let el = $(selector);

            let oldValue = el.data("old-value");

            el.data("old-value", newValue);

            el.text(newValue);


            if (!isFirstLoadCaiApp &&
                oldValue !== undefined &&
                oldValue !== newValue) {

                el.removeClass("highlight-app");

                void el[0].offsetWidth;

                el.addClass("highlight-app");
            }
        }
    });

