        function startWaveLoading(selector, suffixHtml) {
            $(selector).html(`
        <span class="dot-wave">
            <span>.</span><span>.</span><span>.</span>
        </span> ${suffixHtml || ""}
    `);
        }
        function animateNumber(selector, to, duration, suffixHtml) {
            to = Number(to) || 0;

            var start = 0;
            var startTime = null;

            function animate(timestamp) {
                if (!startTime) startTime = timestamp;

                var elapsed = timestamp - startTime;
                var progress = Math.min(elapsed / duration, 1);


                var easedProgress = 1 - Math.pow(1 - progress, 3);

                var current = Math.round(start + (to - start) * easedProgress);


                $(selector).html(current.toLocaleString() + suffixHtml);

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {

                    $(selector).html(to.toLocaleString() + suffixHtml);
                }
            }

            requestAnimationFrame(animate);
        }
        function tinhTiLeSoKH(thucHien, keHoach, labelSelector, progressSelector, tyLeSelector) {

            var $bar = $(progressSelector);
            var html = "";
            if (!keHoach || keHoach <= 0) {

                html = `
            <span class ="text-primary">
               Không có KH
            </span>
        `;
                $(labelSelector).html(html);
                $(tyLeSelector).text("Đạt: 0%");
                $bar.css("width", "0%").attr("aria-valuenow", 0);
                return;
            }

            // TỈ LỆ %
            var tyLe = (thucHien / keHoach) * 100;
            var tyLeLamTron = Math.round(tyLe * 100) / 100; // 2 chữ số
            var chenhlech = tyLeLamTron - 100;



            if (tyLe > 100) {
                html = `
            <span class ="text-success">
                <i class ="mdi mdi-arrow-up-bold text-success"></i>
                ${chenhlech.toFixed(2)}%
            </span>
        `;
            }
            else if (tyLe < 100) {
                html = `
            <span class="text-danger">
                <i class="mdi mdi-arrow-down-bold"></i>
                ${Math.abs(chenhlech).toFixed(2)}%
            </span>
        `;
            }
            //else {
            //    html = `
            //    <span class="text-info">
            //        <i class="mdi mdi-check-circle"></i>
            //        Đạt 100%
            //    </span>
            //`;
            //}
            if (tyLeLamTron > 100) {
                $(labelSelector).html(html);
            }



            var width = Math.min(tyLe, 100);
            $bar.css("width", width + "%");


            $bar.removeClass("bg-success bg-warning bg-danger bg-gradient-primary");

            if (tyLe >= 80) {
                $bar.addClass("bg-success");       // Xanh
            }
            else if (tyLe >= 50) {
                $bar.addClass("bg-warning");       // Vàng
            }
            else {
                $bar.addClass("bg-danger");        // Đỏ
            }


            $(tyLeSelector).text("Đạt: " + tyLeLamTron + "%");


            var width = Math.min(tyLeLamTron, 100); // không quá 100%
            $bar
                .css("width", width + "%")
                .attr("aria-valuenow", tyLeLamTron);


            $bar.removeClass("bg-success bg-warning bg-danger bg-gradient-primary");

            if (tyLeLamTron >= 80) {
                $bar.addClass("bg-success");
            }
            else if (tyLeLamTron >= 50) {
                $bar.addClass("bg-warning");
            }
            else {
                $bar.addClass("bg-danger");
            }
        }
        function tinhTiLeHD0(thucHien, tonghd, kehoach, labelSelector, progressSelector, tyLeSelector) {

